      reasons.push(`Unresolved: ${group.groupId}`);
      pendingTrace('Contextual disagreement requires review');
      continue;
    }
    const selected = response?.resolution.status === 'selected' ?"""
assert old2 in s;s=s.replace(old2,new2)
old3="for (const c of candidates) trace.push({ groupId: group.groupId, candidateId: c.candidateId, decision: 'pending', reason: dispute.reason });"
